import java.io.BufferedWriter
import java.io.OutputStreamWriter

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`), 1024 * 10)
    val writer = BufferedWriter(OutputStreamWriter(System.out), 1024 * 10)

    val n = nextInt(reader)
    val k = nextInt(reader)

    val nn = n.toLong()
    var ex = 1L
    var currentN = n
    var currentK = k

    while (currentN % 10 == 0) {
        currentN /= 10
        currentK--
    }
    while (currentK > 0) {
        if (currentN % 2 == 0) {
            ex *= 5
            currentN /= 2
            currentK--
        } else if (currentN % 5 == 0) {
            ex *= 2
            currentN /= 5
            currentK--
        } else {
            break
        }
    }
    while (currentK > 0) {
        ex *= 10
        currentK--
    }

    writer.write("${ex * nn}\n")
    writer.flush()
}

private fun nextInt(reader: BufferedReader): Int {
    var c: Int
    var res = 0
    var neg = false

    do {
        c = reader.read()
        if (c == -1) return res
    } while (c != '-' && (c < '0' || c > '9'))

    if (c == '-') {
        neg = true
        c = reader.read()
    }

    res = c - '0'
    while (true) {
        c = reader.read()
        if (c < '0' || c > '9') {
            return if (neg) -res else res
        }
        res = res * 10 + (c - '0')
    }
}

