            {
                n /= 10;
                k--;
            }
            while (k > 0)
            {
                if (n%2 == 0)
                {
                    ex *= 5;
                    n /= 2;
                    k--;
                }
                else if (n%5 == 0)
                {
                    ex *= 2;
                    n /= 5;
                    k--;
                }
                else 
                    break;
            }
            while (k > 0)
            {
                ex *= 10;
                k--;
            }

            writer.WriteLine(ex*nn);
            writer.Flush();
        }

        private static int Next()
